# Generated by tools/prepare_public_core.py; see CORE_PROVENANCE.json.
from datetime import timedelta
from .domain import *
from .scope import ResolvedScope
from .reader import open_availability_page, read_availability, map_day_icons

ORIGIN = "https://rsv.shisetsu.city.katsushika.lg.jp"

HEALTH_PROBE = r"""() => {
    const visible = e => !!e && e.getClientRects().length > 0
        && getComputedStyle(e).visibility !== 'hidden';
    const any = selector => [...document.querySelectorAll(selector)].some(visible);
    const text = (document.body?.innerText || '').replace(/\s+/g, ' ');
    return {
        trusted: location.origin === 'https://rsv.shisetsu.city.katsushika.lg.jp',
        manual: any('input[autocomplete="one-time-code"], input[name*="otp" i], input[id*="otp" i], '
            + 'input[name*="captcha" i], input[id*="captcha" i], iframe[src*="recaptcha" i], iframe[src*="hcaptcha" i]'),
        error: [...document.querySelectorAll('[role="alert"], .error, .errorMessage, .errmsg')]
            .some(e => visible(e) && e.textContent.trim()),
        closed: /サービス時間外|サービス停止中|メンテナンス中|ただいま.*利用できません|現在.*サービス.*停止/.test(text)
    };
}"""

DAY_READY = r"""expected => {
    if (document.readyState === 'loading') return false;
    const tables = document.querySelectorAll('table.akitablelist');
    if (tables.length !== 1 || tables[0].rows.length !== 3) return false;
    const rows = [...tables[0].rows];
    const match = rows[0].innerText.match(/(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日/);
    if (!match) return false;
    const actual = `${match[1]}-${match[2].padStart(2,'0')}-${match[3].padStart(2,'0')}`;
    return (expected === null || actual === expected)
        && rows.slice(1).every(row => row.querySelectorAll('td img').length === 7);
}"""

def read_monitoring_day(page):
    return map_day_icons(page, read_availability(page))

def _health(page, http_failed):
    flags = page.evaluate(HEALTH_PROBE)
    if (not isinstance(flags, dict)
            or set(flags) != {"trusted", "manual", "error", "closed"}
            or any(type(value) is not bool for value in flags.values())):
        raise ScanError("READ_ERROR")
    if not flags["trusted"]:
        raise ScanError("UNTRUSTED_ORIGIN")
    if flags["manual"]:
        raise ScanError("MANUAL_ACTION_REQUIRED")
    if flags["closed"] or http_failed():
        raise ScanError("WEBSITE_UNAVAILABLE")
    if flags["error"]:
        raise ScanError("READ_ERROR")

def collect_scope_pages(page, *, scope: ResolvedScope, started_at, clock,
                        http_failed=lambda: False, observer=None, max_duration_seconds=180):
    """Read exactly the resolved inclusive window; never infer its end from AVAILABLE."""
    from playwright.sync_api import Error as PlaywrightError, TimeoutError as PlaywrightTimeout

    days, observations = [], []
    try:
        if started_at.astimezone(JST).date() != scope.start_date:
            raise ScanError("SCAN_WINDOW_CHANGED")
        open_availability_page(page)
        for index in range(scope.expected_days):
            checked_at=clock()
            if checked_at.astimezone(JST).date()!=scope.start_date:
                raise ScanError('SCAN_WINDOW_CHANGED')
            if (checked_at-started_at).total_seconds()>max_duration_seconds:
                raise ScanError('TIMEOUT')
            expected = (scope.start_date + timedelta(days=index)).isoformat()
            page.wait_for_function(DAY_READY, arg=expected, timeout=15000)
            _health(page, http_failed)
            if clock().astimezone(JST).date() != scope.start_date:
                raise ScanError("SCAN_WINDOW_CHANGED")
            if page.locator("table.akitablelist").count() != 1:
                raise ScanError("SOURCE_INCOMPLETE")
            entry = read_monitoring_day(page)
            if observer is not None:
                observer(page, entry)
            day = parse_date(entry["date"])
            if day.isoformat() != expected:
                raise ScanError("UNEXPECTED_DATE")
            slots = availability_rows({"facility": FACILITY, "days": [entry]})
            AvailabilitySnapshot("COMPLETE", None, slots, frozenset({day}))
            if any(slot.status == "UNKNOWN" for slot in slots):
                raise ScanError("UNKNOWN_STATUS")
            _health(page, http_failed)
            days.append(entry)
            observations.append((day, clock()))
            if index + 1 < scope.expected_days:
                next_link = page.get_by_role("link", name="次の日")
                if next_link.count() != 1 or not next_link.is_visible():
                    raise ScanError("BOOKABLE_BOUNDARY_UNVERIFIED")
                next_link.click()
        finished = clock()
        if finished.astimezone(JST).date() != scope.start_date:
            raise ScanError("SCAN_WINDOW_CHANGED")
        return ScanResult.complete(
            {"facility": FACILITY, "days": days},
            started_at=started_at,
            finished_at=finished,
            observations=observations,
            scope_mode=scope.mode,
            boundary_source=scope.boundary_source,
            boundary_verified=scope.boundary_verified,
            expected_days=scope.expected_days,
        )
    except (KeyboardInterrupt, SystemExit):
        raise
    except Exception as error:
        if isinstance(error, ScanError):
            code = error.code
        elif isinstance(error, PlaywrightTimeout):
            code = "TIMEOUT"
        elif isinstance(error, PlaywrightError):
            code = "READ_ERROR"
        elif isinstance(error, (Poc05Error, RuntimeError, ValueError)):
            code = "SOURCE_INCOMPLETE"
        else:
            code = "READ_ERROR"
        if not isinstance(error, ScanError):
            try:
                _health(page, http_failed)
            except ScanError as detected:
                code = detected.code
            except Exception:
                if http_failed():
                    code = "WEBSITE_UNAVAILABLE"
        raise ScanError(code, days_read=len(days), slots_read=len(days) * 14) from None
